def the_readback(case, data):
    """RB — THE READBACK TABLE (THE LOOP's step 6 — the forms on file, no new form): seventy-eight rows one per verse, graded against the kin's cells by CALL and the tape's lines by kind; the rows SUPPLIED with their writes; no receipt, the pointers ahead owed; THE STATE ROW's two arms; THE ONE POINTER ROW 31:10 PAID; the recital a retelling; chapter 31's acts the narrator's present at the marker's day"""
    del P_[:]
    ask = case['ask']
    R = data['the_readback']['value']
    if ask == 'the_table':
        ink('29:1-31:30', 'seventy-eight verses, %d rows; the grades %s' % (len(R), dict(collections.Counter(r['grade'] for r in R))))
        dat('the table a DATA row (the_readback); every row has kin — by CALL %d, on the tape %d' % (sum(1 for r in R if r['cell']), sum(1 for r in R if r['tape_kind'])))
        return out('the readback table (29:1-31:30) — %d rows one per verse, %s; every row graded against its kin' % (len(R), ', '.join('%s %d' % kv for kv in sorted(collections.Counter(r['grade'] for r in R).items()))), ['accepted'])
    if ask == 'the_supplied_rows':
        sup = [r['verses'] for r in R if r['grade'] == 'SUPPLIED']
        ink('29:1-31:30', "the SUPPLIED rows %s — the twenty lines' first verses and the other laws with no seat before" % (sup,))
        dat("the twenty lines' first verses SUPPLIED with their writes and the other holes (the self-blessing, the separation, the end of heaven, the fathers' land, the return's deed, the nearness, the hakhel's children, the doubled hiding, the song's permanence, the song ahead)")
        return out("the supplied rows — %s: the code's holes compiled at the chapters' own days" % (', '.join(sup),), ['accepted'])
    if ask == 'the_reference_rows':
        ref = [(r['verses'], r['tape_kind'], r['tape_verse']) for r in R if r['tape_kind']]
        ink('29:1-2, 29:5-8, 29:11-12, 29:16-17, 29:19, 29:21-22, 29:24, 29:26-28, 30:1-2, 30:6-7, 30:9, 30:12, 30:14-20, 31:1-11, 31:14-22, 31:24-29', 'the reference rows %s' % (ref,))
        dat("the T1 rows against the tape's lines by kind and first verse — the plagues and the going out, the manna, the kings, the covenant's blood, the people this day, the ten words, the inciter, the plagues scattered, the pair set, the heart's circumcision, the release, the booths, the pilgrimages, the place, the king's copy, the war's speech, the witnesses, the testimony, Joshua encouraged and commissioned, the journeys written, the fragments in the ark, the calf, the testament, the sea's song — never a second act (THE RETELLING RULES)")
        return out("the reference rows — %d against the tape's lines (the plagues, the manna, the kings, Sinai's covenant, the people this day, the ten words, the inciter, the plagues scattered, the pair set, the heart, the release, the booths, the pilgrimages, the place, the king, the war, the witnesses, the testimony, Joshua's charges, the writings, the ark, the calf, the testament, the song): retellings, never a second act" % (len(ref),), ['accepted'])
    if ask == 'the_receipts':
        rc = data['the_receipts']['value']
        ink('29:1-31:30', 'the receipt seats by the finder %s — NONE in the three chapters; the register file untouched; the pointers ahead 1 Kings 9:8, Nehemiah 1:9, Joshua 1:5-9, 4:19, 5:12, 8:34, Micah 7:5, Psalms 47:10' % (rc,))
        dat("no receipt, header or footer in the three chapters (good_land.receipt_seats(29..31) -> [], [], []); THE POINTERS AHEAD OWED under the lean pass's debt line — no pointer row for them; the three AS_WHEN pointers RUN CITATIONS, the two comparatives FALSE")
        return out("the receipts (29:1-31:30) — none by the finder's own count; the register file untouched; the pointers ahead owed: 1 Kings 9:8, Nehemiah 1:9, Joshua 1:5-9, 4:19, 5:12, 8:34, Micah 7:5, Psalms 47:10", ['accepted'])
    if ask == 'the_state_and_the_pointers':
        ink('30:15, 30:17, 31:10', 'state rows %s, pointer rows %s, open rows %s, stretch rows %s' % ([r['verses'] for r in R if r['state']], [(r['verses'], r['pointer']['referent'][:40], r['pointer']['grade']) for r in R if r['pointer']], [r['verses'] for r in R if r['open']], [r['verses'] for r in R if r['stretch']]))
        dat("THE STATE ROW life and death's two arms (13b's form — 15:4 / 15:11 the precedent; 28:1 / 28:15 the second); THE ONE POINTER ROW 31:10 PAID — 15b's owed row for 31:10 graded R (a reference): the copy of the law's seat forward (17:18-19); no open row (Berakhot 9:2's dispute recorded with its arms), no stretch")
        return out("the state row at 30:15 and 30:17 (life and death — the two arms); the pointer row at 31:10 PAID (15b's owed — the copy of the law's seat forward, a reference); no open, no stretch row — the forms on file, no new form", ['accepted'])
